    const diving = h < 2200 && alt > 550 && -dz < h * 0.7 && a.f.x * dx + a.f.y * dy > 0;
    aim = diving ? v3(dx, dy, dz) : v3(dx, dy, clampN((A.CRUISE_ALT - alt) / 1500, -0.25, 0.35) * h);
    if (alt < 550 && !diving) aim = v3(dx, dy, h * 0.5);
